import React, { useEffect, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Trash2, Menu, Edit3, Eye } from "lucide-react";

interface BasicMapProps {
  polygon: any;
  onPolygonChange: (polygon: any) => void;
  generatedRoute: any;
  sidebarOpen: boolean;
  onToggleSidebar?: () => void;
}

export default function BasicMap({
  polygon,
  onPolygonChange,
  generatedRoute,
  sidebarOpen,
  onToggleSidebar,
}: BasicMapProps) {
  const mapRef = useRef<HTMLDivElement>(null);
  const [mapReady, setMapReady] = useState(false);
  const [error, setError] = useState<string>("");
  const [isDrawing, setIsDrawing] = useState(false);
  const [sketch, setSketch] = useState<any>(null);
  const [mapView, setMapView] = useState<any>(null);
  const [routeLayer, setRouteLayer] = useState<any>(null);
  const [showWaypoints, setShowWaypoints] = useState(false);

  useEffect(() => {
    let view: any = null;

    const initializeMap = async () => {
      if (!mapRef.current) return;

      try {
        // Wait for Esri to be available
        if (typeof (window as any).require === 'undefined') {
          throw new Error('Esri API not loaded');
        }

        const [Map, MapView, Sketch, GraphicsLayer, Graphic, SimpleLineSymbol, SimpleMarkerSymbol, FeatureLayer] = await new Promise((resolve, reject) => {
          (window as any).require([
            "esri/Map",
            "esri/views/MapView",
            "esri/widgets/Sketch",
            "esri/layers/GraphicsLayer",
            "esri/Graphic",
            "esri/symbols/SimpleLineSymbol",
            "esri/symbols/SimpleMarkerSymbol",
            "esri/layers/FeatureLayer"
          ], (...modules: any[]) => {
            resolve(modules);
          }, (error: any) => {
            reject(error);
          });
        });

        // Create feature layers for lease boundaries and bedding documentation
        const leaseBoundariesLayer = new (FeatureLayer as any)({
          url: "https://services.arcgis.com/W1AXaDPef2QMa9kU/arcgis/rest/services/Lease_Boundaries/FeatureServer/0",
          title: "Lease Boundaries",
          opacity: 0.7,
          outFields: ["*"]
        });

        const beddingDocumentationLayer = new (FeatureLayer as any)({
          url: "https://services.arcgis.com/W1AXaDPef2QMa9kU/arcgis/rest/services/Bedding_Documentation_view/FeatureServer/0",
          title: "Bedding Documentation", 
          opacity: 0.8,
          outFields: ["*"]
        });

        // Log layer loading
        console.log("Loading Lease Boundaries and Bedding Documentation layers...");

        // Create graphics layers for drawing and routes
        const graphicsLayer = new (GraphicsLayer as any)();
        const routeGraphicsLayer = new (GraphicsLayer as any)();

        const map = new (Map as any)({
          basemap: "satellite",
          layers: [leaseBoundariesLayer, beddingDocumentationLayer, graphicsLayer, routeGraphicsLayer]
        });

        view = new (MapView as any)({
          container: mapRef.current,
          map: map,
          center: [-94.7977, 29.3013], // Galveston Bay, TX
          zoom: 11
        });

        // Create sketch widget
        const sketchWidget = new (Sketch as any)({
          layer: graphicsLayer,
          view: view,
          creationMode: "single",
          availableCreateTools: ["polygon"],
          visibleElements: {
            createTools: {
              point: false,
              polyline: false,
              rectangle: false,
              circle: false
            },
            selectionTools: {
              "rectangle-selection": false,
              "lasso-selection": false
            },
            settingsMenu: false,
            undoRedoMenu: false
          }
        });

        // Handle sketch events
        sketchWidget.on("create", (event: any) => {
          if (event.state === "complete") {
            const geometry = event.graphic.geometry;
            if (geometry && geometry.type === "polygon" && geometry.rings && geometry.rings.length > 0) {
              const coordinates = geometry.rings[0].map((ring: number[]) => [ring[0], ring[1]]);
              // Ensure polygon is closed
              if (coordinates[0][0] !== coordinates[coordinates.length - 1][0] || 
                  coordinates[0][1] !== coordinates[coordinates.length - 1][1]) {
                coordinates.push([coordinates[0][0], coordinates[0][1]]);
              }
              const geoJsonPolygon = {
                type: "Polygon",
                coordinates: [coordinates]
              };
              onPolygonChange(geoJsonPolygon);
              setIsDrawing(false);
              view.ui.remove(sketchWidget);
            }
          }
        });

        await view.when();

        // Wait for layers to load
        try {
          await Promise.all([
            leaseBoundariesLayer.when(),
            beddingDocumentationLayer.when()
          ]);
          console.log("All layers loaded successfully");
        } catch (layerError) {
          console.warn("Some layers failed to load:", layerError);
        }

        console.log("Basic map initialized successfully");
        setMapView(view);
        setSketch(sketchWidget);
        setRouteLayer(routeGraphicsLayer);
        setMapReady(true);
        setError("");

      } catch (err) {
        console.error("Map initialization error:", err);
        setError(err instanceof Error ? err.message : "Map failed to load");
        setMapReady(false);
      }
    };

    // Initialize after a short delay
    const timer = setTimeout(initializeMap, 200);

    return () => {
      clearTimeout(timer);
      if (view) {
        try {
          view.destroy();
        } catch (e) {
          console.warn("Error destroying map view:", e);
        }
      }
    };
  }, []);

  // Display generated route on map with level-of-detail optimization
  useEffect(() => {
    if (!mapView || !routeLayer || !generatedRoute) return;

    (window as any).require([
      "esri/Graphic",
      "esri/geometry/Polyline", 
      "esri/geometry/Point",
      "esri/symbols/SimpleLineSymbol",
      "esri/symbols/SimpleMarkerSymbol"
    ], (Graphic: any, Polyline: any, Point: any, SimpleLineSymbol: any, SimpleMarkerSymbol: any) => {
      // Clear existing route graphics
      routeLayer.removeAll();

      // Add transect lines (always show these)
      if (generatedRoute.transectLines) {
        try {
          const graphics = generatedRoute.transectLines.map((line: any, index: number) => {
            const esriPolyline = new Polyline({
              paths: [line.geometry.coordinates],
              spatialReference: { wkid: 4326 }
            });

            return new Graphic({
              geometry: esriPolyline,
              symbol: new SimpleLineSymbol({
                color: index % 2 === 0 ? [255, 0, 0, 0.8] : [0, 255, 0, 0.8],
                width: 2
              })
            });
          });

          // Add graphics in batches to prevent overwhelming the renderer
          routeLayer.addMany(graphics);
        } catch (error) {
          console.warn('Error adding route lines:', error);
        }
      }

      // Add waypoints with level-of-detail (only show when zoomed in)
      let updateTimeout: NodeJS.Timeout | null = null;

      const updateWaypoints = () => {
        // Clear existing timeout to debounce updates
        if (updateTimeout) {
          clearTimeout(updateTimeout);
        }

        updateTimeout = setTimeout(() => {
          try {
            const zoom = mapView.zoom;
            const shouldShowWaypoints = showWaypoints && zoom > 14; // Only show when user enables and zoomed in

            // Remove existing waypoints
            const waypointGraphics = routeLayer.graphics.filter((g: any) => 
              g.symbol && g.symbol.type === 'simple-marker'
            ).toArray();

            routeLayer.removeMany(waypointGraphics);

            if (shouldShowWaypoints && generatedRoute.waypoints) {
              // Very conservative waypoint limits to prevent performance issues
              const maxWaypoints = Math.min(50, generatedRoute.waypoints.length);
              const step = Math.ceil(generatedRoute.waypoints.length / maxWaypoints);

              const waypointBatch = generatedRoute.waypoints
                .filter((_: any, i: number) => i % step === 0)
                .map((waypoint: any) => {
                  const point = new Point({
                    longitude: waypoint.lng,
                    latitude: waypoint.lat,
                    spatialReference: { wkid: 4326 }
                  });

                  return new Graphic({
                    geometry: point,
                    symbol: new SimpleMarkerSymbol({
                      color: [255, 255, 0, 0.8],
                      size: 3,
                      outline: {
                        color: [0, 0, 0, 0.6],
                        width: 1
                      }
                    })
                  });
                });

              if (waypointBatch.length > 0) {
                routeLayer.addMany(waypointBatch);
              }
            }
          } catch (error) {
            console.warn('Error updating waypoints:', error);
          }
        }, 250); // 250ms debounce delay
      };

      // Initial waypoint update
      updateWaypoints();

      // Watch for zoom changes to update waypoint visibility (throttled)
      const zoomHandle = mapView.watch('zoom', updateWaypoints);

      // Clean up any existing watcher
      if ((routeLayer as any).zoomHandle) {
        (routeLayer as any).zoomHandle.remove();
      }

      // Store cleanup function
      (routeLayer as any).zoomHandle = zoomHandle;

      console.log("Route displayed on map:", generatedRoute.transectLines?.length, "lines");
    });
  }, [generatedRoute, mapView, routeLayer, showWaypoints]);

  const handleClear = () => {
    if (sketch && mapView) {
      try {
        sketch.cancel();
        mapView.ui.remove(sketch);
      } catch (e) {
        // Ignore errors
      }
      setIsDrawing(false);
    }

    // Clear route graphics and cleanup watchers
    if (routeLayer) {
      // Clean up zoom watcher if it exists
      if ((routeLayer as any).zoomHandle) {
        (routeLayer as any).zoomHandle.remove();
        (routeLayer as any).zoomHandle = null;
      }
      routeLayer.removeAll();
    }

    onPolygonChange(null);
  };

  const handleDrawPolygon = () => {
    if (!sketch || !mapView) return;

    if (isDrawing) {
      // Cancel drawing
      try {
        sketch.cancel();
        mapView.ui.remove(sketch);
      } catch (e) {
        // Ignore errors
      }
      setIsDrawing(false);
    } else {
      // Start drawing
      const graphicsLayer = mapView.map.layers.getItemAt(0);
      if (graphicsLayer) {
        graphicsLayer.removeAll();
      }

      mapView.ui.add(sketch, "top-right");
      setIsDrawing(true);

      setTimeout(() => {
        try {
          sketch.create("polygon");
        } catch (e) {
          console.warn("Could not start polygon creation:", e);
        }
      }, 100);
    }
  };

  return (
    <div className="relative h-full w-full bg-gray-100">
      {/* Map Container */}
      <div
        ref={mapRef}
        className="h-full w-full"
        style={{ 
          height: "100vh",
          width: "100%",
          minHeight: "400px"
        }}
      />

      {/* Error Display */}
      {error && (
        <div className="absolute inset-0 flex items-center justify-center bg-gray-100">
          <Card className="p-6 max-w-md">
            <h3 className="text-lg font-semibold text-red-600 mb-2">Map Error</h3>
            <p className="text-sm text-gray-600 mb-4">{error}</p>
            <Button onClick={() => window.location.reload()} variant="outline">
              Reload Page
            </Button>
          </Card>
        </div>
      )}

      {/* Loading Indicator */}
      {!mapReady && !error && (
        <div className="absolute inset-0 flex items-center justify-center bg-gray-100">
          <Card className="p-6">
            <div className="flex items-center space-x-3">
              <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-blue-600"></div>
              <span className="text-sm">Loading Esri Map...</span>
            </div>
          </Card>
        </div>
      )}

      {/* Mobile-friendly Sidebar Toggle */}
      <div className="absolute top-4 left-4 z-20">
        <Button
          onClick={onToggleSidebar}
          variant="default"
          size="icon"
          className="bg-blue-600 hover:bg-blue-700 text-white shadow-lg touch-manipulation min-h-[44px] min-w-[44px]"
        >
          <Menu className="h-5 w-5" />
        </Button>
      </div>

      {/* Mobile-optimized Controls */}
      {mapReady && (
        <div className="absolute top-4 right-4 z-10">
          <Card className="p-2 space-y-2">
            <Button
              variant={isDrawing ? "default" : "outline"}
              size="sm"
              onClick={handleDrawPolygon}
              className="w-full touch-manipulation min-h-[36px] text-xs sm:text-sm"
            >
              <Edit3 className="h-4 w-4 mr-1 sm:mr-2" />
              <span className="hidden sm:inline">{isDrawing ? "Cancel Draw" : "Draw Polygon"}</span>
              <span className="sm:hidden">{isDrawing ? "Cancel" : "Draw"}</span>
            </Button>

            <Button
              variant="outline"
              size="sm"
              onClick={handleClear}
              className="w-full text-red-600 hover:text-red-700 touch-manipulation min-h-[36px] text-xs sm:text-sm"
            >
              <Trash2 className="h-4 w-4 mr-1 sm:mr-2" />
              Clear
            </Button>

            {generatedRoute && (
              <Button
                variant={showWaypoints ? "default" : "outline"}
                size="sm"
                onClick={() => setShowWaypoints(!showWaypoints)}
                className="w-full touch-manipulation min-h-[36px] text-xs sm:text-sm"
              >
                <Eye className="h-4 w-4 mr-1 sm:mr-2" />
                <span className="hidden sm:inline">{showWaypoints ? "Hide Points" : "Show Points"}</span>
                <span className="sm:hidden">{showWaypoints ? "Hide" : "Show"}</span>
              </Button>
            )}
          </Card>
        </div>
      )}

      {/* Mobile-optimized Status */}
      <div className="absolute bottom-4 left-4 z-10 max-w-[calc(100vw-2rem)] sm:max-w-none">
        <Card className="p-2 sm:p-3">
          <div className="text-xs sm:text-sm font-medium">
            Status: {mapReady ? "Ready" : error ? "Error" : "Loading..."}
          </div>
          {generatedRoute && (
            <div className="text-xs text-gray-600 mt-1">
              {generatedRoute.transectLines?.length || 0} lines, {generatedRoute.waypoints?.length || 0} points
            </div>
          )}
          {polygon && !generatedRoute && (
            <div className="text-xs text-gray-600 mt-1">
              Polygon loaded
            </div>
          )}
          {isDrawing && (
            <div className="text-xs text-blue-600 mt-1">
              <span className="hidden sm:inline">Click to draw polygon points</span>
              <span className="sm:hidden">Tap to draw</span>
            </div>
          )}
        </Card>
      </div>
    </div>
  );
}

