import { useState, useRef } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { CloudUpload, FileText, Trash2, Pencil } from "lucide-react";
import { cn } from "@/lib/utils";
import { apiRequest, apiFormDataRequest } from "@/lib/queryClient";

interface PolygonInputProps {
  polygon: any;
  onPolygonChange: (polygon: any) => void;
  onError: (error: string) => void;
  onStartDrawing?: () => void;
  onClearMap?: () => void;
}

export default function PolygonInput({
  polygon,
  onPolygonChange,
  onError,
  onStartDrawing,
  onClearMap,
}: PolygonInputProps) {
  const [activeTab, setActiveTab] = useState<"upload" | "draw">("draw");
  const [uploadedFiles, setUploadedFiles] = useState<any[]>([]);
  const [isDragOver, setIsDragOver] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = async (files: FileList) => {
    try {
      const formData = new FormData();
      Array.from(files).forEach((file) => {
        formData.append("files", file);
      });

      const response = await apiFormDataRequest("POST", "/api/upload-polygon", formData);
      const result = await response.json();

      if (result.polygons && result.polygons.length > 0) {
        setUploadedFiles(result.files || []);
        onPolygonChange(result.polygons[0]); // Use first polygon
      } else {
        onError("No valid polygons found in uploaded files");
      }
    } catch (error) {
      console.error("File upload error:", error);
      onError("Failed to upload and process files: " + (error instanceof Error ? error.message : "Unknown error"));
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragOver(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragOver(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragOver(false);

    const files = e.dataTransfer.files;
    if (files && files.length > 0) {
      handleFileUpload(files);
    }
  };

  const handleFileInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files.length > 0) {
      handleFileUpload(files);
    }
  };

  const removeFile = (index: number) => {
    const newFiles = uploadedFiles.filter((_, i) => i !== index);
    setUploadedFiles(newFiles);
    if (newFiles.length === 0) {
      onPolygonChange(null);
    }
  };

  const clearPolygon = () => {
    onPolygonChange(null);
    setUploadedFiles([]);
    // Call the map clear function if available
    if (onClearMap) {
      onClearMap();
    } else if ((window as any).mapClearFunction) {
      (window as any).mapClearFunction();
    }
  };



  return (
    <Card className="border-0 border-b border-gray-100 rounded-none">
      <CardHeader>
        <CardTitle className="text-lg">Define Area</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Tab Toggle */}
        <div className="flex rounded-lg bg-gray-100 p-1">
          <Button
            variant={activeTab === "draw" ? "default" : "ghost"}
            size="sm"
            onClick={() => setActiveTab("draw")}
            className="flex-1"
          >
            Draw Polygon
          </Button>
          <Button
            variant={activeTab === "upload" ? "default" : "ghost"}
            size="sm"
            onClick={() => setActiveTab("upload")}
            className="flex-1"
          >
            Upload File
          </Button>
        </div>

        {/* Upload Section */}
        {activeTab === "upload" && (
          <div className="space-y-4">
            <div
              className={cn(
                "file-upload-area rounded-lg p-6 text-center cursor-pointer transition-all",
                isDragOver && "drag-over"
              )}
              onDragOver={handleDragOver}
              onDragLeave={handleDragLeave}
              onDrop={handleDrop}
              onClick={() => fileInputRef.current?.click()}
            >
              <CloudUpload className="h-8 w-8 text-gray-400 mb-2 mx-auto" />
              <p className="text-sm font-medium text-gray-700">
                Drop KML or SHP files here
              </p>
              <p className="text-xs text-gray-500 mt-1">or click to browse</p>
              <Input
                ref={fileInputRef}
                type="file"
                className="hidden"
                accept=".kml,.shp,.zip"
                multiple
                onChange={handleFileInputChange}
              />
            </div>

            {uploadedFiles.length > 0 && (
              <div className="space-y-2">
                {uploadedFiles.map((file, index) => (
                  <div
                    key={index}
                    className="flex items-center justify-between p-3 bg-gray-50 rounded-lg"
                  >
                    <div className="flex items-center space-x-3">
                      <FileText className="h-4 w-4 text-gray-400" />
                      <span className="text-sm font-medium text-gray-700">
                        {file.fileName}
                      </span>
                    </div>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => removeFile(index)}
                      className="text-red-500 hover:text-red-700"
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Draw Section */}
        {activeTab === "draw" && (
          <div className="space-y-4">
            <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
              <div className="flex items-center mb-2">
                <div className="w-4 h-4 bg-blue-500 rounded-full mr-2"></div>
                <p className="text-sm text-blue-700 font-medium">
                  Drawing Instructions:
                </p>
              </div>
              <div className="text-sm text-blue-600 space-y-1">
                <p>1. Look for the drawing controls on the map (top-left corner)</p>
                <p>2. Click the polygon tool (square icon)</p>
                <p>3. Click points on the map to create your survey area</p>
                <p>4. Double-click to finish the polygon</p>
              </div>
            </div>

            <div className="flex space-x-2">
              <Button
                variant="outline"
                size="sm"
                onClick={clearPolygon}
              >
                <Trash2 className="h-4 w-4 mr-2" />
                Clear All
              </Button>
            </div>

            {polygon && (
              <div className="bg-green-50 border border-green-200 rounded-lg p-3">
                <p className="text-sm text-green-700">
                  ✓ Polygon ready! You can now generate a route.
                </p>
              </div>
            )}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

client/src/components/route-generation.t.content:
import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Slider } from "@/components/ui/slider";
import { Route, Clock, MapPin, Navigation, Gauge } from "lucide-react";
import { RouteParameters } from "@shared/schema";
import { apiRequest } from "@/lib/queryClient";
import { Loader2 } from "lucide-react";

interface RouteGenerationProps {
  polygon: any;
  parameters: RouteParameters;
  generatedRoute: any;
  isGenerating: boolean;
  onRouteGenerated: (route: any) => void;
  onError: (error: string) => void;
}

export default function RouteGeneration({
  polygon,
  parameters,
  generatedRoute,
  isGenerating,
  onRouteGenerated,
  onError,
}: RouteGenerationProps) {
  const [localGenerating, setLocalGenerating] = useState(false);
  const [speed, setSpeed] = useState(20); // Default speed in kph
  const [routeName, setRouteName] = useState("Survey Route 1");

  // Speed conversion functions
  const convertSpeed = (speedKph: number) => {
    return {
      kph: speedKph,
      mph: speedKph * 0.621371,
      knots: speedKph * 0.539957,
    };
  };

  // Calculate estimated time based on total distance and speed
  const calculateEstimatedTime = (totalDistanceMeters: number, speedKph: number) => {
    if (!totalDistanceMeters || speedKph <= 0) return 0;
    const distanceKm = totalDistanceMeters / 1000;
    const timeHours = distanceKm / speedKph;
    return Math.round(timeHours * 60); // Convert to minutes
  };

  const handleGenerateRoute = async () => {
    if (!polygon) {
      onError("Please define a polygon first");
      return;
    }

    setLocalGenerating(true);
    try {
      const response = await apiRequest("POST", "/api/generate-route", {
        polygon,
        parameters,
        name: routeName.trim() || "Survey Route 1",
      });

      const result = await response.json();
      onRouteGenerated(result);
    } catch (error) {
      onError("Failed to generate route");
    } finally {
      setLocalGenerating(false);
    }
  };

  const isGeneratingRoute = isGenerating || localGenerating;
  const hasRoute = generatedRoute && generatedRoute.waypoints;
  const speedConversions = convertSpeed(speed);
  const dynamicEstimatedTime = hasRoute ? calculateEstimatedTime(generatedRoute.totalDistance, speed) : 0;

  return (
    <Card className="border-0 border-b border-gray-100 rounded-none">
      <CardHeader>
        <CardTitle className="text-lg">Generate Route</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Route Name Input */}
        <div className="space-y-2">
          <Label htmlFor="routeName" className="text-sm font-medium">
            Route Name
          </Label>
          <Input
            id="routeName"
            type="text"
            value={routeName}
            onChange={(e) => setRouteName(e.target.value)}
            placeholder="Enter route name (e.g., Survey Area 1)"
            className="w-full"
          />
          <p className="text-xs text-gray-500">
            This name will be used in the exported GPX and KML files
          </p>
        </div>

        <Button
          onClick={handleGenerateRoute}
          disabled={!polygon || isGeneratingRoute}
          className="w-full"
          size="lg"
        >
          {isGeneratingRoute ? (
            <>
              <Loader2 className="h-4 w-4 mr-2 animate-spin" />
              Generating Route...
            </>
          ) : (
            <>
              <Route className="h-4 w-4 mr-2" />
              Generate Transect Route
            </>
          )}
        </Button>

        {/* Route Statistics */}
        {hasRoute && (
          <div className="bg-gray-50 rounded-lg p-4">
            <h3 className="text-sm font-medium text-gray-700 mb-2">
              Route Statistics
            </h3>
            <div className="grid grid-cols-2 gap-3 text-sm">
              <div className="flex items-center space-x-2">
                <Navigation className="h-4 w-4 text-gray-400" />
                <div>
                  <span className="text-gray-500">Total Distance:</span>
                  <span className="font-medium ml-1">
                    {generatedRoute.totalDistance ? 
                      `${(generatedRoute.totalDistance / 1000).toFixed(1)} km` : 
                      'N/A'
                    }
                  </span>
                </div>
              </div>

              <div className="flex items-center space-x-2">
                <Route className="h-4 w-4 text-gray-400" />
                <div>
                  <span className="text-gray-500">Transect Lines:</span>
                  <span className="font-medium ml-1">
                    {generatedRoute.transectLines?.length || 0}
                  </span>
                </div>
              </div>

              <div className="flex items-center space-x-2">
                <MapPin className="h-4 w-4 text-gray-400" />
                <div>
                  <span className="text-gray-500">Waypoints:</span>
                  <span className="font-medium ml-1">
                    {generatedRoute.waypoints?.length || 0}
                  </span>
                </div>
              </div>

              <div className="col-span-2">
                <div className="flex items-center space-x-2 mb-3">
                  <Gauge className="h-4 w-4 text-gray-400" />
                  <span className="text-gray-500 font-medium">Speed Control</span>
                </div>

                <div className="space-y-3">
                  <Slider
                    value={[speed]}
                    onValueChange={(value) => setSpeed(value[0])}
                    max={60}
                    min={5}
                    step={1}
                    className="w-full"
                  />

                  {/* Speed Scale */}
                  <div className="grid grid-cols-3 gap-2 text-xs">
                    <div className="text-center bg-blue-50 rounded px-2 py-1">
                      <div className="font-medium text-blue-700">{speedConversions.kph.toFixed(1)}</div>
                      <div className="text-blue-600">kph</div>
                    </div>
                    <div className="text-center bg-green-50 rounded px-2 py-1">
                      <div className="font-medium text-green-700">{speedConversions.mph.toFixed(1)}</div>
                      <div className="text-green-600">mph</div>
                    </div>
                    <div className="text-center bg-purple-50 rounded px-2 py-1">
                      <div className="font-medium text-purple-700">{speedConversions.knots.toFixed(1)}</div>
                      <div className="text-purple-600">knots</div>
                    </div>
                  </div>

                  {/* Dynamic Time Display */}
                  <div className="flex items-center justify-center space-x-2 bg-gray-100 rounded-lg py-2">
                    <Clock className="h-4 w-4 text-gray-600" />
                    <span className="text-sm text-gray-600">Estimated Time:</span>
                    <span className="font-bold text-gray-900">
                      {dynamicEstimatedTime > 0 ? 
                        `${Math.floor(dynamicEstimatedTime / 60)}h ${dynamicEstimatedTime % 60}m` : 
                        'N/A'
                      }
                    </span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

